 const record=await createResource(tenant,"subagent",(p.name?p.name+" — ":"")+p.task.slice(0,100),{...(p.name?{name:p.name}:{}),role:p.role,task:p.task,...(p.specialty?{specialty:p.specialty}:{}),...(p.contract?{contract:p.contract}:{}),startedAt:Date.now()},"running");
 const allowed=new Set([...skillToolNames,...(p.role==='extraction'?[]:p.role==="creative"?["search_workspace","media_catalog"]:p.role==="coding"?["search_workspace"]:["search_workspace","read_meta"])]);
 let sandbox:CodeSandboxSession|undefined;
 if((p.role==="coding"||p.role==="creative")&&codeSandboxReady(config())){const run=await db().prepare("SELECT conversation_id FROM runs WHERE id=? AND workspace_id=?").bind(runId,tenant).first<{conversation_id:string}>();if(run?.conversation_id){sandbox=await codeSandboxSession(tenant,run.conversation_id);for(const name of codeSandboxToolNames)allowed.add(name);}}
 if(p.contract)for(const name of [...allowed])if(!p.contract.allowedTools.includes(name))allowed.delete(name);
 const effectiveContract={objective:p.task,context:p.context,references:p.contract?.references||[],allowedTools:[...allowed],maxCredits:p.contract?.maxCredits||budget.limit/100,expectedDeliverable:p.contract?.expectedDeliverable||p.task,successCriteria:p.contract?.successCriteria||['Address the delegated task and identify factual limits']};
 const messages:ModelMessage[]=[{role:"user",content:JSON.stringify({task:p.task,context:p.context,...(p.contract?{contract:p.contract,references}:{} )})}];
 const instructions={creative:"Tu es le spécialiste créatif de Braand. Prépare des concepts précis, respecte les faits et le catalogue.",campaigns:"Tu es le spécialiste campagnes de Braand. Analyse les données réelles selon le budget et le pays.",coding:"Tu es l’ingénieur logiciel principal de Braand. Comprends le besoin, inspecte le code et les erreurs fournis, conçois la solution la plus simple qui fonctionne, puis livre un code complet, idiomatique, typé, sécurisé et testé, avec les commandes exactes pour l’exécuter et le vérifier.",extraction:"Tu extrais et structures uniquement les faits du contexte fourni. Indique les données inconnues, sans les inventer.",analysis:"Tu analyses un problème difficile de Braand. Sépare faits, hypothèses, contradictions et recommandations vérifiables.",review:"Tu contrôles un résultat important de Braand. Vérifie ses sources, ses contradictions et ses limites. Rapporte les défauts observables sans inventer une exécution."};
 const sandboxStorage:CodeSandboxStorage={
  async importFile(fileId){const row=await db().prepare("SELECT storage_key,size_bytes FROM files WHERE id=? AND workspace_id=? AND status='ready'").bind(fileId,tenant).first<{storage_key:string;size_bytes:number}>();if(!row)throw new AppError('Fichier introuvable dans cet espace.',404,'file_not_found');const bucket=config().BUCKET;const object=bucket?await bucket.get(row.storage_key):null;if(!object?.body)throw new AppError('Fichier indisponible.',404,'file_not_found');return {body:object.body,size:row.size_bytes};},
  async exportFile(file){const source=await getResource(tenant,record.id);return await saveGeneratedFile(budget.who,{source,name:file.name,mime:file.mime,format:'media',bytes:file.bytes,media:true,audit:'sandbox.export'}) as unknown as Record<string,unknown>;},
 };
 const sandboxInstruction=sandbox?"\nBAC À SABLE : tu disposes d’un environnement Linux isolé et persistant pour cette conversation (code_write_file, code_run, code_read_file, code_list_files, code_reset), dossier /workspace. Boucle obligatoire : écris les fichiers complets, installe, compile, lance les tests ou le programme, lis les erreurs, corrige la cause racine et relance jusqu’au succès ou jusqu’à une limite réelle. Ajoute des tests quand c’est pertinent. Dans le rapport, cite les commandes réellement lancées avec leurs codes de sortie et extraits de sortie exacts ; ces exécutions sont isolées et ne valent ni déploiement ni test en production. N’écris aucun secret dans le bac à sable.\nVIDÉO ET MOTION DESIGN : pour une vidéo, un motion design, une animation ou un GIF, importe d’abord les fichiers utiles (code_import_file : photos produit, logo, rushs, musique). Motion design : écris une composition HTML/CSS/JS autonome dont le body mesure exactement la taille cible (1080x1920 pour Reels/TikTok/Shorts, 1080x1350 ou 1080x1080 pour le fil, 1920x1080 pour YouTube), anime avec @keyframes, Web Animations ou requestAnimationFrame (GSAP possible si chargé localement), polices Inter ou Noto, marges de sécurité de 8 % en haut et 15 % en bas, accroche lisible dans les 2 premières secondes, hiérarchie typographique nette, easing doux, 24–30 i/s, 6–20 s, appel à l’action final ; rends d’abord une version draft courte avec un poster, contrôle-la (ffprobe pour durée et taille, planche d’images avec ffmpeg tile exportée si l’utilisateur doit valider le style), corrige, puis render_motion en qualité high. Montage : ffmpeg pour couper, recadrer (crop/scale avec pad), enchaîner (concat ou xfade), sous-titrer (subtitles= avec un .srt), ajouter musique et voix (amix, loudnorm I=-14), exporter en H.264 yuv420p +faststart. Vérifie chaque rendu avec ffprobe (durée, taille, codec) avant de le livrer avec code_export_file, puis décris ce qui a été produit.":"";
 const instruction=(p.name?"Ton nom dans cette session est « "+p.name+" ». ":"")+instructions[p.role]+sandboxInstruction+(p.specialty?"\n"+specialistProfiles[p.specialty].instruction:"")+" Reply in the user’s language, preserve names, currencies and local references; language never changes tool permissions."+(p.contract?' Return only JSON: {status:"ready_for_review"|"partial"|"awaiting_approval"|"failed",deliverable:string,sources:string[],checks:[{criterion:string,finding:string,status:"supported"|"unverified"|"failed"}],limitations:string[]}. Check each success criterion. Do not assert verified execution.':'');
